<p className="mb-4">"Działaj jako ekspert od strategii treści dla dziecięcego kanału na YouTube. Moim celem jest tworzenie angażujących i bezpiecznych filmów dla dzieci w wieku [Twój wiek, np. 10 lat]. Stwórz dla mnie szczegółowy plan treści na najbliższe 2 tygodnie.</p>

